#ifndef SOUNDS_H
#define SOUNDS_H
#include <stddef.h>
#include <stdint.h>

/* 16 kHz mono PCM, generated by python/convert_to_c.py */
extern const int16_t switch_on_s[6915];
extern const int16_t switch_off_s[5637];

/* play_sound(SOUND(switch_on_s)) -> passes the array and its length */
#define SOUND(x) (x), (sizeof(x) / sizeof((x)[0]))
/* the error beeps are generated in code, see error_stream() in main.c */
#define ERROR_SOUND NULL, 0

#endif
